from support import *
import time
def main():
    required=['verification.json','extra_verification.json','bootstrap_verification.json','conditional_verification.json','cpu_replay.json','gap_verification.json','oracle_verification.json']
    while not all((HERE/x).exists() for x in required):time.sleep(3)
